import { test, expect } from '@playwright/test';

test.describe('Modal Dialog - Escape Key Close Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-dialog');
  });

  test('should close modal when Escape key is pressed', async ({ page }) => {
    // Open modal by clicking the open button
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modalContainer = page.locator('[data-testid="modal-container"]');
    await expect(modalContainer).toBeVisible();

    // Verify modal title is displayed
    const modalTitle = page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).toBeVisible();

    // Verify close button is visible
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Press Escape key to close modal
    await page.keyboard.press('Escape');

    // Verify modal is no longer visible
    await expect(modalContainer).not.toBeVisible();

    // Verify modal title is no longer visible
    await expect(modalTitle).not.toBeVisible();

    // Verify close button is no longer visible
    await expect(closeButton).not.toBeVisible();
  });

  test('should not close modal when Escape key is pressed while modal is not open', async ({ page }) => {
    // Verify modal is not visible initially
    const modalContainer = page.locator('[data-testid="modal-container"]');
    await expect(modalContainer).not.toBeVisible();

    // Press Escape key when modal is closed
    await page.keyboard.press('Escape');

    // Verify modal remains closed
    await expect(modalContainer).not.toBeVisible();

    // Verify modal title is not visible
    const modalTitle = page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).not.toBeVisible();

    // Open modal by clicking the open button
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is now visible
    await expect(modalContainer).toBeVisible();

    // Press Escape key again
    await page.keyboard.press('Escape');

    // Verify modal is closed
    await expect(modalContainer).not.toBeVisible();
  });
});
